import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/child_service.dart';class ChildConsultationScreen extends StatefulWidget{const ChildConsultationScreen({super.key});@override State<ChildConsultationScreen>createState()=>_S();}class _S extends State<ChildConsultationScreen>{final q=TextEditingController();bool busy=false;Future<void>send()async{final u=FirebaseAuth.instance.currentUser;if(u==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('سجل الدخول أولاً')));return;}if(q.text.trim().isEmpty)return;setState(()=>busy=true);try{await ChildService().createConsultation(userId:u.uid,question:q.text.trim());q.clear();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال الاستشارة')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('استشارة الأطفال')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[TextField(controller:q,maxLines:6,decoration:const InputDecoration(labelText:'اكتب سؤالاً عن طفلك',border:OutlineInputBorder())),const SizedBox(height:16),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:busy?null:send,child:Text(busy?'جارٍ الإرسال...':'إرسال الاستشارة')))])));}}
